# Build individual .rda files for the OlinkViz package
# NOTE: This script requires the raw .Rdata files generated by
# convert_all_to_rdata.R (run from the original Public_Olink_Data directory).
# The raw .Rdata files are not bundled with the package to avoid sync issues.
# The final .rda files are already in data/ — re-run this script only after
# re-acquiring raw source data and re-running convert_all_to_rdata.R.

workspace_root <- dirname(dirname(getwd()))
cat("Workspace root:", workspace_root, "\n")

data_dir <- file.path(dirname(getwd()), "data")

# ---- Load each .Rdata and save individual .rda ----

# 1. IRIS Long COVID
cat("\n1. IRIS Long COVID\n")
load(file.path(workspace_root, "IRIS_LongCOVID_olink_data.Rdata"))
stopifnot(exists("iris_longcovid"))
save(iris_longcovid, file = file.path(data_dir, "iris_longcovid.rda"),
     compress = "gzip")
cat("  -> iris_longcovid.rda\n")

# 2. PCNSL
cat("2. PCNSL\n")
load(file.path(workspace_root, "PCNSL_olink_data.Rdata"))
stopifnot(exists("pcnsl_olink"))
save(pcnsl_olink, file = file.path(data_dir, "pcnsl_olink.rda"),
     compress = "gzip")
cat("  -> pcnsl_olink.rda\n")

# 3. BeatMG (3 objects)
cat("3. BeatMG\n")
load(file.path(workspace_root, "BeatMG_olink_data.Rdata"))
stopifnot(exists("beatmg_npx"), exists("beatmg_demo"), exists("beatmg_npx_merged"))
save(beatmg_npx, file = file.path(data_dir, "beatmg_npx.rda"),
     compress = "gzip")
save(beatmg_demo, file = file.path(data_dir, "beatmg_demo.rda"),
     compress = "gzip")
save(beatmg_npx_merged, file = file.path(data_dir, "beatmg_npx_merged.rda"),
     compress = "gzip")
cat("  -> beatmg_npx.rda, beatmg_demo.rda, beatmg_npx_merged.rda\n")

# 4. Bansal (3 objects)
cat("4. Bansal\n")
load(file.path(workspace_root, "Bansal_LongCOVID_olink_data.Rdata"))
stopifnot(exists("bansal_baseline57"), exists("bansal_univariate"),
          exists("bansal_longitudinal"))
save(bansal_baseline57, file = file.path(data_dir, "bansal_baseline57.rda"),
     compress = "gzip")
save(bansal_univariate, file = file.path(data_dir, "bansal_univariate.rda"),
     compress = "gzip")
save(bansal_longitudinal, file = file.path(data_dir, "bansal_longitudinal.rda"),
     compress = "gzip")
cat("  -> bansal_baseline57.rda, bansal_univariate.rda, bansal_longitudinal.rda\n")

# 5. Qinfeng TB
cat("5. Qinfeng TB\n")
load(file.path(workspace_root, "Qinfeng_TB_olink_data.Rdata"))
stopifnot(exists("qinfeng_npx"))
save(qinfeng_npx, file = file.path(data_dir, "qinfeng_npx.rda"),
     compress = "gzip")
cat("  -> qinfeng_npx.rda\n")

# 6. TOFA (2 objects)
cat("6. TOFA\n")
load(file.path(workspace_root, "TOFA_DownSyndrome_olink_data.Rdata"))
stopifnot(exists("tofa_data"), exists("tofa_dictionary"))
save(tofa_data, file = file.path(data_dir, "tofa_data.rda"),
     compress = "gzip")
save(tofa_dictionary, file = file.path(data_dir, "tofa_dictionary.rda"),
     compress = "gzip")
cat("  -> tofa_data.rda, tofa_dictionary.rda\n")

# ---- Summary ----
cat("\nDone. Files in data/:")
for (f in sort(list.files(data_dir, pattern = "\\.rda$"))) {
  sz <- file.info(file.path(data_dir, f))$size
  cat(sprintf("  %-40s %s\n", f, format(sz, big.mark = ",", scientific = FALSE)))
}
